command:
set -euo pipefail; git fetch origin main; git reset --hard origin/main; test -z "$(git status --porcelain)"; cd projects/kobra2-neo; JOB=/tmp/kobra-chat-ready.L2ygbI/job; G="$JOB/output.gcode"; R="$JOB/report.json"; test -f "$G"; test -f "$R"; SHA=$(shasum -a 256 "$G" | awk '{print $1}'); test "$SHA" = "18989085c5031f3e55e60b9103450d18435a0f872451e48b737cdc453bb2a8f4"; uv sync --frozen >/dev/null; PORT=$(uv run python - <<'PY'
from glob import glob
from kobra_live import PosixSerial, _identify
matches=[]
for port in sorted(glob('/dev/cu.usbserial-*')):
    try:
        with PosixSerial(port) as serial:
            _identify(serial)
        matches.append(port)
    except Exception:
        pass
if len(matches) != 1:
    raise SystemExit(f'expected exactly one Anycubic Kobra, found {matches}')
print(matches[0])
PY
); echo RESULT:PORT_IDENTIFIED port=$PORT; uv run kobra-live "$G" --report "$R" --profile config/kobra2_neo_pen.toml --port "$PORT" --expect-sha256 "$SHA" --progress-every 100 --thermal-check-every 250
